<?php session_start();require __DIR__.'/config/database.php';$rows=[];if(isset($_SESSION['user_id'])){$s=$pdo->prepare('SELECT game,amount,multiplier,result,created_at FROM game_history WHERE user_id=? ORDER BY id DESC LIMIT 50');$s->execute([$_SESSION['user_id']]);$rows=$s->fetchAll();}?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>История — DROP</title><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="app"><main class="page"><div class="game-header"><h1>История</h1><a class="muted" href="index.php">Назад</a></div><section class="card" style="padding:14px"><?php if(!$rows):?><p class="muted">История пока пуста.</p><?php else:foreach($rows as $r):?><div style="padding:12px 0;border-bottom:1px solid var(--line)"><b><?=htmlspecialchars($r['game'])?></b> · <?=number_format($r['amount'],2,'.',' ')?> · <?=htmlspecialchars($r['result'])?><small class="muted" style="display:block"><?=htmlspecialchars($r['created_at'])?></small></div><?php endforeach;endif;?></section></main></div></body></html>